var step_3_default = "---\nlayout: tutorial\ntitle: Set up Appwrite\ndescription: Import and initialize Appwrite for your React Native application.\nstep: 3\n---\n\n## Create project {% #create-project %}\n\nHead to the [Appwrite Console](https://cloud.appwrite.io/console).\n\n{% only_dark %}\n![Create project screen](/images/docs/quick-starts/dark/create-project.avif)\n{% /only_dark %}\n{% only_light %}\n![Create project screen](/images/docs/quick-starts/create-project.avif)\n{% /only_light %}\n\nIf this is your first time using Appwrite, create an account and create your first project.\n\nThen, under **Add a platform**, add a **Android** or **Apple** platform with the package/bundle ID `com.example.idea-tracker`. \n\n{% only_dark %}\n![Add a platform](/images/docs/quick-starts/dark/add-platform.avif)\n{% /only_dark %}\n{% only_light %}\n![Add a platform](/images/docs/quick-starts/add-platform.avif)\n{% /only_light %}\n\nYou can skip optional steps.\n\n## Initialize Appwrite SDK {% #init-sdk %}\n\nTo use Appwrite in our React Native app, you'll need to find our project ID. \nFind your project's ID in the **Settings** page. \n\n{% only_dark %}\n![Project settings screen](/images/docs/quick-starts/dark/project-id.avif)\n{% /only_dark %}\n{% only_light %}\n![Project settings screen](/images/docs/quick-starts/project-id.avif)\n{% /only_light %}\n\nCreate a new file `lib/appwrite.js` to hold our Appwrite related code.\nOnly one instance of the `Client()` class should be created per app.\nAdd the following code to it, replacing `<PROJECT_ID>` with your project ID.\n\n```js\nimport { Client, TablesDB, Account } from \"react-native-appwrite\";\n\nconst client = new Client();\nclient\n  .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\")\n  .setProject(\"<PROJECT_ID>\") // Replace with your project ID\n  .setPlatform('com.example.idea-tracker');\n\n\nexport const account = new Account(client);\nexport const tablesDB = new TablesDB(client);\n```\n";
export { step_3_default as default };
